def _unescape(raw_token):
    out = []
    i = 0
    while i < len(raw_token):
        ch = raw_token[i]
        if ch == "~":
            if i + 1 >= len(raw_token) or raw_token[i+1] not in "01":
                raise InvalidCorrection(...)
            out.append("~" if raw_token[i+1] == "0" else "/")
            i += 2
        else:
            out.append(ch)
            i += 1
    return "".join(out)
```

