```python
def process_subject_requests(payload):
    if not isinstance(payload, dict):
        raise InvalidRequest("request body must be a JSON object")
    raw_records = payload.get("records")
    if not isinstance(raw_records, list) or not raw_records:
        raise InvalidRequest("records must be a non-empty array")
    raw_requests = payload.get("requests")
    if not isinstance(raw_requests, list) or not raw_requests:
        raise InvalidRequest("requests must be a non-empty array")

    records = [_parse_record(r) for r in raw_records]
    seen = set()
    for record in records:
        if record["record_id"] in seen:
            raise InvalidRecord("record_id must be unique within the request")
        seen.add(record["record_id"])

    requests = [_parse_request(r) for r in raw_requests]
    seen = set()
    for req in requests:
        if req["request_id"] in seen:
            raise InvalidSubjectRequest("request_id must be unique within the request")
        seen.add(req["request_id"])

    working = [
        {"record_id": r["record_id"], "subject_id": r["subject_id"], "data": copy.deepcopy(r["data"])}
        for r in records
    ]
    by_id = {r["record_id"]: r for r in working}

    results = []
    for req in requests:
        results.append(_apply_request(req, working, by_id))

    final_records = [
        {"record_id": r["record_id"], "subject_id": r["subject_id"], "data": r["data"]}
        for r in working
    ]
    return {"results": results, "records": final_records}
```

_apply_request:

```python
def _apply_request(request, records, by_id):
    base = {"request_id": request["request_id"]}
    if not request["verified"]:
        return {**base, "status": "rejected", "reason": "identity_not_verified"}
    req_type = request["type"]
    if req_type == "export":
        matched = sorted(
            (r for r in records if r["subject_id"] == request["subject_id"]),
            key=lambda r: r["record_id"],
        )
        return {**base, "status": "exported",
                "records": [{"record_id": r["record_id"], "data": copy.deepcopy(r["data"])} for r in matched]}
    if req_type == "delete":
        matched_ids = sorted(r["record_id"] for r in records if r["subject_id"] == request["subject_id"])
        if matched_ids:
            remove = set(matched_ids)
